INSERT INTO `email_templates` (`id`, `code`, `name`, `subject_template`, `body_template`, `channel`, `variables_hint`, `status`, `created_at`, `updated_at`) VALUES
(1, 'booking_payment_verified_bus', 'Bus Payment Verified', 'Your bus booking {{booking_code}} is confirmed', '<p>Dear {{customer_name}},</p><p>Your bus booking <strong>{{booking_code}}</strong> has been verified successfully.</p><p>Route: <strong>{{from_city}} → {{to_city}}</strong></p><p>Trip Date: <strong>{{trip_date}}</strong></p><p>Ticket No: <strong>{{ticket_no}}</strong></p><p>Total Amount: <strong>{{amount}}</strong></p><p>You can view your ticket here:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>Thank you,<br>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{from_city}}, {{to_city}}, {{trip_date}}, {{ticket_no}}, {{amount}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(2, 'booking_payment_verified_tour', 'Tour Payment Verified', 'Your tour booking {{booking_code}} is confirmed', '<p>Dear {{customer_name}},</p><p>Your tour booking <strong>{{booking_code}}</strong> has been verified successfully.</p><p>Package: <strong>{{package_title}}</strong></p><p>Batch Date: <strong>{{batch_date}}</strong></p><p>Voucher Code: <strong>{{voucher_code}}</strong></p><p>Total Amount: <strong>{{amount}}</strong></p><p>You can view your voucher here:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>Thank you,<br>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{package_title}}, {{batch_date}}, {{voucher_code}}, {{amount}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(3, 'refund_request_received_customer', 'Refund Request Received (Customer)', 'Refund request received for {{booking_code}}', '<p>Dear {{customer_name}},</p><p>We received your refund request for booking <strong>{{booking_code}}</strong>.</p><p>Request Code: <strong>{{request_code}}</strong></p><p>Requested Amount: <strong>{{amount}}</strong></p><p>Status: <strong>{{status}}</strong></p><p>You can track the request here:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{request_code}}, {{amount}}, {{status}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(4, 'refund_request_received_admin', 'Refund Request Received (Admin)', 'New refund request {{request_code}} for {{booking_code}}', '<p>Hello Admin,</p><p>A new refund request has been submitted.</p><p>Request Code: <strong>{{request_code}}</strong></p><p>Booking Code: <strong>{{booking_code}}</strong></p><p>Customer: <strong>{{customer_name}}</strong></p><p>Amount: <strong>{{amount}}</strong></p><p>Open request:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>{{app_name}}</p>', 'both', '{{request_code}}, {{booking_code}}, {{customer_name}}, {{amount}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(5, 'refund_approved_customer', 'Refund Approved', 'Refund approved for {{booking_code}}', '<p>Dear {{customer_name}},</p><p>Your refund request for booking <strong>{{booking_code}}</strong> has been approved.</p><p>Request Code: <strong>{{request_code}}</strong></p><p>Amount: <strong>{{amount}}</strong></p><p>Status: <strong>{{status}}</strong></p><p>Track here:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{request_code}}, {{amount}}, {{status}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(6, 'refund_rejected_customer', 'Refund Rejected', 'Refund rejected for {{booking_code}}', '<p>Dear {{customer_name}},</p><p>Your refund request for booking <strong>{{booking_code}}</strong> has been rejected.</p><p>Request Code: <strong>{{request_code}}</strong></p><p>Status: <strong>{{status}}</strong></p><p>Track here:</p><p><a href=\"{{action_url}}\">{{action_url}}</a></p><p>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{request_code}}, {{status}}, {{action_url}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(7, 'trip_boarded_customer', 'Bus Boarding Checked In', 'Boarding confirmed for ticket {{ticket_no}}', '<p>Dear {{customer_name}},</p><p>Your bus boarding has been confirmed.</p><p>Booking Code: <strong>{{booking_code}}</strong></p><p>Ticket No: <strong>{{ticket_no}}</strong></p><p>Route: <strong>{{from_city}} → {{to_city}}</strong></p><p>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{ticket_no}}, {{from_city}}, {{to_city}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(8, 'voucher_checked_in_customer', 'Tour Check-in Confirmed', 'Check-in confirmed for voucher {{voucher_code}}', '<p>Dear {{customer_name}},</p><p>Your tour check-in has been confirmed.</p><p>Booking Code: <strong>{{booking_code}}</strong></p><p>Voucher Code: <strong>{{voucher_code}}</strong></p><p>Package: <strong>{{package_title}}</strong></p><p>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{voucher_code}}, {{package_title}}, {{app_name}}', 'active', '2026-04-04 20:10:52', '2026-04-04 20:10:52'),
(9, 'booking_created_customer', 'Booking Created (Customer)', 'Your booking {{booking_code}} has been created', '<p>Dear {{customer_name}},</p>\r\n     <p>Your booking <strong>{{booking_code}}</strong> has been created successfully.</p>\r\n     <p>Route: <strong>{{from_city}} → {{to_city}}</strong></p>\r\n     <p>Trip Date: <strong>{{trip_date}}</strong></p>\r\n     <p>Seats: <strong>{{seat_numbers}}</strong></p>\r\n     <p>Passengers: <strong>{{passenger_count}}</strong></p>\r\n     <p>Total Amount: <strong>{{amount}}</strong></p>\r\n     <p>Status: <strong>{{status}}</strong></p>\r\n     <p>You can continue payment here:</p>\r\n     <p><a href=\"{{action_url}}\">{{action_url}}</a></p>\r\n     <p>Thank you,<br>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{from_city}}, {{to_city}}, {{trip_date}}, {{seat_numbers}}, {{passenger_count}}, {{amount}}, {{status}}, {{action_url}}, {{app_name}}', 'active', '2026-04-09 10:57:45', '2026-04-09 10:57:45'),
(10, 'payment_submitted_customer', 'Payment Submitted (Customer)', 'Your payment for {{booking_code}} is pending review', '<p>Dear {{customer_name}},</p>\r\n     <p>We received your payment submission for booking <strong>{{booking_code}}</strong>.</p>\r\n     <p>Payment Method: <strong>{{payment_method}}</strong></p>\r\n     <p>Amount: <strong>{{amount}}</strong></p>\r\n     <p>Transaction Reference: <strong>{{transaction_ref}}</strong></p>\r\n     <p>Status: <strong>{{status}}</strong></p>\r\n     <p>You can view your booking here:</p>\r\n     <p><a href=\"{{action_url}}\">{{action_url}}</a></p>\r\n     <p>Thank you,<br>{{app_name}}</p>', 'both', '{{customer_name}}, {{booking_code}}, {{payment_method}}, {{amount}}, {{transaction_ref}}, {{status}}, {{action_url}}, {{app_name}}', 'active', '2026-04-09 10:57:45', '2026-04-09 10:57:45');
